const MOD int64 = 998244353

type Edge struct {
	from, to int
	weight   int
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func berlekampMassey(s []int64) []int64 {
	C := []int64{1}
	B := []int64{1}
	L, shift := 0, 1
	b := int64(1)

	for n := 0; n < len(s); n++ {
		d := s[n]
		for i := 1; i <= L; i++ {
			d = (d + C[i]*s[n-i]) % MOD
		}

		if d == 0 {
			shift++
			continue
		}

		oldC := append([]int64(nil), C...)
		coef := d * modPow(b, MOD-2) % MOD

		need := len(B) + shift
		if len(C) < need {
			C = append(C, make([]int64, need-len(C))...)
		}
		for i := 0; i < len(B); i++ {
			C[i+shift] = (C[i+shift] - coef*B[i]) % MOD
			if C[i+shift] < 0 {
				C[i+shift] += MOD
			}
		}

		if 2*L <= n {
			L = n + 1 - L
			B = oldC
			b = d
			shift = 1
		} else {
			shift++
		}
	}

	rec := make([]int64, L)
	for i := 0; i < L; i++ {
		rec[i] = (MOD - C[i+1]) % MOD
	}
	return rec
}

func combine(a, b, rec []int64) []int64 {
	k := len(rec)
	tmp := make([]int64, 2*k-1)

	for i := 0; i < k; i++ {
		if a[i] == 0 {
			continue
		}
		for j := 0; j < k; j++ {
			if b[j] == 0 {
				continue
			}
			tmp[i+j] = (tmp[i+j] + a[i]*b[j]) % MOD
		}
	}

	for degree := 2*k - 2; degree >= k; degree-- {
		v := tmp[degree]
		if v == 0 {
			continue
		}
		for j := 0; j < k; j++ {
			idx := degree - 1 - j
			tmp[idx] = (tmp[idx] + v*rec[j]) % MOD
		}
	}

	return tmp[:k]
}

func linearTerm(initial, rec []int64, n int64) int64 {
	if n < int64(len(initial)) {
		return initial[n]
	}

	k := len(rec)
	if k == 0 {
		return 0
	}

	result := make([]int64, k)
	result[0] = 1

	base := make([]int64, k)
	if k == 1 {
		base[0] = rec[0]
	} else {
		base[1] = 1
	}

	for n > 0 {
		if n&1 == 1 {
			result = combine(result, base, rec)
		}
		base = combine(base, base, rec)
		n >>= 1
	}

	ans := int64(0)
	for i := 0; i < k; i++ {
		ans = (ans + result[i]*initial[i]) % MOD
	}
	return ans
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	words := make([]string, n)
	for i := range words {
		fmt.Fscan(in, &words[i])
	}

	suffixIndex := make(map[string]int)
