	for _, word := range words {
		for i := 1; i < len(word); i++ {
			s := word[i:]
			if _, exists := suffixIndex[s]; !exists {
				suffixIndex[s] = len(suffixes)
				suffixes = append(suffixes, s)
			}
		}
	}

	topState := func(s string) int {
		return 1 + 2*suffixIndex[s]
	}
	bottomState := func(s string) int {
		return 2 + 2*suffixIndex[s]
	}

	stateCount := 1 + 2*len(suffixes)
	edges := make([]Edge, 0)

	// Both hints start a new word.
	for _, topWord := range words {
		for _, bottomWord := range words {
			if topWord == bottomWord {
				edges = append(edges, Edge{0, 0, len(topWord)})
			} else if strings.HasPrefix(topWord, bottomWord) {
				residual := topWord[len(bottomWord):]
				edges = append(edges, Edge{0, topState(residual), len(bottomWord)})
			} else if strings.HasPrefix(bottomWord, topWord) {
				residual := bottomWord[len(topWord):]
				edges = append(edges, Edge{0, bottomState(residual), len(topWord)})
			}
		}
	}

	for _, residual := range suffixes {
		top := topState(residual)
		bottom := bottomState(residual)

		// The top hint is ahead; the bottom hint starts a word.
		for _, word := range words {
			if residual == word {
				edges = append(edges, Edge{top, 0, len(word)})
			} else if strings.HasPrefix(residual, word) {
				next := residual[len(word):]
				edges = append(edges, Edge{top, topState(next), len(word)})
			} else if strings.HasPrefix(word, residual) {
				next := word[len(residual):]
				edges = append(edges, Edge{top, bottomState(next), len(residual)})
			}
		}

		// The bottom hint is ahead; the top hint starts a word.
		for _, word := range words {
			if residual == word {
				edges = append(edges, Edge{bottom, 0, len(word)})
			} else if strings.HasPrefix(residual, word) {
				next := residual[len(word):]
				edges = append(edges, Edge{bottom, bottomState(next), len(word)})
			} else if strings.HasPrefix(word, residual) {
				next := word[len(residual):]
				edges = append(edges, Edge{bottom, topState(next), len(residual)})
			}
		}
	}

	orderBound := 5 * stateCount
	termCount := 2*orderBound + 10

	dp := make([][]int64, termCount)
	for i := range dp {
		dp[i] = make([]int64, stateCount)
	}
	dp[0][0] = 1

	sequence := make([]int64, termCount)
	sequence[0] = 1

