const mod int64 = 998244353

type Edge struct {
	src, dst int
	length   int
	count    int64
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
