func berlekampMassey(s []int64) []int64 {
	c := []int64{1}
	b := []int64{1}
	l, shift := 0, 1
	last := int64(1)

	for pos := 0; pos < len(s); pos++ {
		discrepancy := s[pos]
		for i := 1; i <= l; i++ {
			discrepancy = (discrepancy + c[i]*s[pos-i]) % mod
		}

		if discrepancy == 0 {
			shift++
			continue
		}

		oldC := append([]int64(nil), c...)
		factor := discrepancy * modPow(last, mod-2) % mod

		need := len(b) + shift
		if len(c) < need {
			c = append(c, make([]int64, need-len(c))...)
		}
		for i := 0; i < len(b); i++ {
			c[i+shift] = (c[i+shift] - factor*b[i]) % mod
			if c[i+shift] < 0 {
				c[i+shift] += mod
			}
		}

		if 2*l <= pos {
			l = pos + 1 - l
			b = oldC
			last = discrepancy
			shift = 1
		} else {
			shift++
		}
	}

	if len(c) < l+1 {
		c = append(c, make([]int64, l+1-len(c))...)
	}
	rec := make([]int64, l)
	for i := 0; i < l; i++ {
		rec[i] = (mod - c[i+1]) % mod
	}
	return rec
}

func combine(a, b, rec []int64) []int64 {
	k := len(rec)
	tmp := make([]int64, 2*k-1)

	for i := 0; i < k; i++ {
		if a[i] == 0 {
			continue
		}
		for j := 0; j < k; j++ {
			if b[j] == 0 {
				continue
			}
			tmp[i+j] = (tmp[i+j] + a[i]*b[j]) % mod
		}
	}

	for degree := 2*k - 2; degree >= k; degree-- {
		if tmp[degree] == 0 {
			continue
		}
		value := tmp[degree]
		for j := 0; j < k; j++ {
			idx := degree - 1 - j
			tmp[idx] = (tmp[idx] + value*rec[j]) % mod
		}
	}
	return tmp[:k]
}

func linearRecurrenceTerm(sequence, rec []int64, index int64) int64 {
	if index < int64(len(sequence)) {
		return sequence[index]
	}

	k := len(rec)
	if k == 0 {
		return 0
	}

	result := make([]int64, k)
	base := make([]int64, k)
	result[0] = 1
	if k == 1 {
		base[0] = rec[0]
	} else {
		base[1] = 1
	}

	for index > 0 {
		if index&1 == 1 {
			result = combine(result, base, rec)
		}
		base = combine(base, base, rec)
		index >>= 1
	}

	answer := int64(0)
	for i := 0; i < k; i++ {
		answer = (answer + result[i]*sequence[i]) % mod
	}
	return answer
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	words := make([]string, n)
	for i := range words {
		fmt.Fscan(in, &words[i])
	}

	// State 0 means both concatenations are equal.
	// Other states mean that the second concatenation is ahead by a suffix.
	suffixIndex := make(map[string]int)
	suffixes := make([]string, 0)

	for _, word := range words {
		for i := 0; i < len(word); i++ {
			suffix := word[i:]
			if _, exists := suffixIndex[suffix]; !exists {
				suffixes = append(suffixes, suffix)
				suffixIndex[suffix] = len(suffixes)
			}
		}
	}

	stateCount := len(suffixes) + 1

	// closure(r) counts ways to append words to the second hint until
	// the first hint is no longer ahead by r.
	memo := make(map[string][]int64)
	var closure func(string) []int64

	closure = func(r string) []int64 {
		if result, ok := memo[r]; ok {
			return result
		}

		result := make([]int64, stateCount)
		memo[r] = result

		for _, word := range words {
			if strings.HasPrefix(r, word) {
				if len(r) == len(word) {
					result[0]++
					if result[0] == mod {
						result[0] = 0
					}
				} else {
					next := closure(r[len(word):])
					for i, value := range next {
						result[i] = (result[i] + value) % mod
					}
				}
			} else if strings.HasPrefix(word, r) {
				remaining := word[len(r):]
				dst := suffixIndex[remaining]
				result[dst]++
				if result[dst] == mod {
					result[dst] = 0
				}
			}
		}
		return result
	}

	edges := make([]Edge, 0)

	for src := 0; src < stateCount; src++ {
		type key struct {
			dst, length int
		}
		acc := make(map[key]int64)

		for _, word := range words {
			var destinations []int64

			if src == 0 {
				destinations = closure(word)
			} else {
				r := suffixes[src-1]
				destinations = make([]int64, stateCount)

				if strings.HasPrefix(r, word) {
					if len(r) == len(word) {
						destinations[0] = 1
					} else {
						destinations[suffixIndex[r[len(word):]]] = 1
					}
				} else if strings.HasPrefix(word, r) {
					destinations = closure(word[len(r):])
				} else {
					continue
				}
			}

			for dst, count := range destinations {
				if count == 0 {
					continue
				}
				k := key{dst: dst, length: len(word)}
				acc[k] = (acc[k] + count) % mod
			}
		}

		for k, count := range acc {
			edges = append(edges, Edge{
				src:    src,
				dst:    k.dst,
				length: k.length,
				count:  count,
			})
		}
	}

	maxOrder := 5 * stateCount
	termCount := 2*maxOrder + 20

	dp := make([][]int64, termCount)
	for i := range dp {
		dp[i] = make([]int64, stateCount)
	}
	dp[0][0] = 1

	sequence := make([]int64, termCount)
	sequence[0] = 1

	for length := 1; length < termCount; length++ {
		for _, edge := range edges {
			if length < edge.length {
				continue
			}
			value := dp[length-edge.length][edge.src]
			if value == 0 {
				continue
			}
			dp[length][edge.dst] = (dp[length][edge.dst] + value*edge.count) % mod
		}
		sequence[length] = dp[length][0]
	}

	recurrence := berlekampMassey(sequence)
	answer := linearRecurrenceTerm(sequence, recurrence, m)

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

