func combine(a, b, rec []int64) []int64 {
	k := len(rec)
	tmp := make([]int64, 2*k-1)

	for i := 0; i < k; i++ {
		if a[i] == 0 {
			continue
		}
		for j := 0; j < k; j++ {
			if b[j] == 0 {
				continue
			}
			tmp[i+j] = (tmp[i+j] + a[i]*b[j]) % MOD
		}
	}

	for i := 2*k - 2; i >= k; i-- {
		if tmp[i] == 0 {
			continue
		}
		v := tmp[i]
		for j := 1; j <= k; j++ {
			tmp[i-j] = (tmp[i-j] + v*rec[j-1]) % MOD
		}
	}

	return tmp[:k]
}

func linearNth(initial, rec []int64, n int64) int64 {
	if n < int64(len(initial)) {
		return initial[n]
	}

	k := len(rec)
	result := make([]int64, k)
	base := make([]int64, k)
	result[0] = 1

	if k == 1 {
		base[0] = rec[0]
	} else {
		base[1] = 1
	}

	for n > 0 {
		if n&1 == 1 {
			result = combine(result, base, rec)
		}
		base = combine(base, base, rec)
		n >>= 1
