func compatible(a, b string) bool {
	length := len(a)
	if len(b) < length {
		length = len(b)
	}
	for i := 0; i < length; i++ {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	words := make([]string, n)
	for i := range words {
		fmt.Fscan(in, &words[i])
	}

	residueIndex := make(map[string]int)
	residues := make([]string, 0)

	for _, word := range words {
		for start := 1; start < len(word); start++ {
			suffix := word[start:]
			if _, exists := residueIndex[suffix]; !exists {
				residueIndex[suffix] = len(residues)
				residues = append(residues, suffix)
			}
		}
	}

	stateID := func(residue string, orientation int) int {
		idx := residueIndex[residue]
		if orientation == 1 {
			return 1 + 2*idx
		}
		return 2 + 2*idx
	}

	stateCount := 1 + 2*len(residues)
	edges := make([]Edge, 0)

	// From the equal state, choose the next word of both hints.
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			a, b := words[i], words[j]
			if !compatible(a, b) {
				continue
			}

			weight := len(a)
			if len(b) < weight {
				weight = len(b)
			}

			to := 0
			if len(a) > len(b) {
				to = stateID(a[len(b):], 1)
			} else if len(b) > len(a) {
				to = stateID(b[len(a):], -1)
			}
			edges = append(edges, Edge{0, to, weight})
		}
	}

	// From an unequal state, choose a word for the currently shorter hint.
	for idx, residue := range residues {
		for _, orientation := range []int{1, -1} {
			from := 1 + 2*idx
			if orientation == -1 {
				from++
			}

			for _, word := range words {
				if !compatible(residue, word) {
					continue
				}

				weight := len(residue)
				if len(word) < weight {
					weight = len(word)
				}

				to := 0
				if len(residue) > len(word) {
					to = stateID(residue[len(word):], orientation)
				} else if len(word) > len(residue) {
					to = stateID(word[len(residue):], -orientation)
				}

				edges = append(edges, Edge{from, to, weight})
			}
		}
	}

	maxOrder := 5 * stateCount
	termCount := 2*maxOrder + 20

	dp := make([][]int64, termCount)
	for i := range dp {
		dp[i] = make([]int64, stateCount)
	}
	dp[0][0] = 1

	for length := 0; length < termCount; length++ {
		for _, edge := range edges {
			next := length + edge.weight
			if next >= termCount || dp[length][edge.from] == 0 {
				continue
			}
			dp[next][edge.to] += dp[length][edge.from]
			if dp[next][edge.to] >= MOD {
				dp[next][edge.to] -= MOD
			}
		}
	}

	sequence := make([]int64, termCount)
	for i := range sequence {
		sequence[i] = dp[i][0]
	}

	if m < int64(termCount) {
		fmt.Println(sequence[m])
		return
	}

	recurrence := berlekampMassey(sequence)
	initial := sequence[:len(recurrence)]
	fmt.Println(linearNth(initial, recurrence, m))
}

