const mod int64 = 998244353

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func berlekampMassey(s []int64) []int64 {
	c := []int64{1}
	bPoly := []int64{1}
	l, shift := 0, 1
	lastDiscrepancy := int64(1)

	for n := 0; n < len(s); n++ {
		d := s[n]
		for i := 1; i <= l; i++ {
			d = (d + c[i]*s[n-i]) % mod
		}

		if d == 0 {
			shift++
			continue
		}

		coef := d * modPow(lastDiscrepancy, mod-2) % mod
		oldC := append([]int64(nil), c...)

		needed := len(bPoly) + shift
		if len(c) < needed {
			c = append(c, make([]int64, needed-len(c))...)
		}

		for i := 0; i < len(bPoly); i++ {
			idx := i + shift
			c[idx] = (c[idx] - coef*bPoly[i]) % mod
			if c[idx] < 0 {
				c[idx] += mod
			}
		}

		if 2*l <= n {
			l = n + 1 - l
			bPoly = oldC
			lastDiscrepancy = d
			shift = 1
		} else {
			shift++
		}
	}

	rec := make([]int64, l)
	for i := 0; i < l; i++ {
		rec[i] = (mod - c[i+1]) % mod
	}
	return rec
}

func combine(a, b, rec []int64) []int64 {
	l := len(rec)
	tmp := make([]int64, 2*l-1)

	for i := 0; i < l; i++ {
		if a[i] == 0 {
			continue
		}
		for j := 0; j < l; j++ {
			if b[j] == 0 {
				continue
			}
			tmp[i+j] = (tmp[i+j] + a[i]*b[j]) % mod
		}
	}

	for i := 2*l - 2; i >= l; i-- {
		if tmp[i] == 0 {
			continue
		}
		v := tmp[i]
		for j := 0; j < l; j++ {
			idx := i - 1 - j
			tmp[idx] = (tmp[idx] + v*rec[j]) % mod
		}
	}

	return tmp[:l]
}

func linearRecurrenceNth(initial, rec []int64, n int64) int64 {
	if n < int64(len(initial)) {
		return initial[n]
	}

	l := len(rec)
	if l == 0 {
		return 0
	}

	result := make([]int64, l)
	result[0] = 1

	base := make([]int64, l)
	if l == 1 {
		base[0] = rec[0]
	} else {
		base[1] = 1
	}

	for n > 0 {
		if n&1 == 1 {
			result = combine(result, base, rec)
		}
		n >>= 1
		if n > 0 {
			base = combine(base, base, rec)
		}
	}

	answer := int64(0)
	for i := 0; i < l; i++ {
		answer = (answer + result[i]*initial[i]) % mod
	}
	return answer
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	words := make([]string, n)
	isWord := make(map[string]bool)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &words[i])
		isWord[words[i]] = true
	}

	prefixes := []string{""}
	prefixID := map[string]int{"": 0}

	for _, word := range words {
		for length := 1; length < len(word); length++ {
			prefix := word[:length]
			if _, exists := prefixID[prefix]; !exists {
				prefixID[prefix] = len(prefixes)
				prefixes = append(prefixes, prefix)
			}
		}
	}

	p := len(prefixes)
	transitions := make([][26][]int, p)

	for i, prefix := range prefixes {
		for ch := byte('a'); ch <= byte('z'); ch++ {
			next := prefix + string(ch)
			idx := int(ch - 'a')

			if id, exists := prefixID[next]; exists {
				transitions[i][idx] = append(transitions[i][idx], id)
			}
			if isWord[next] {
				transitions[i][idx] = append(transitions[i][idx], 0)
			}
		}
	}

	fullSize := p * p
	fullEdges := make([][]int, fullSize)
	reverseEdges := make([][]int, fullSize)

	for a := 0; a < p; a++ {
		for b := 0; b < p; b++ {
			from := a*p + b
			for ch := 0; ch < 26; ch++ {
				left := transitions[a][ch]
				right := transitions[b][ch]
				for _, x := range left {
					for _, y := range right {
						to := x*p + y
						fullEdges[from] = append(fullEdges[from], to)
						reverseEdges[to] = append(reverseEdges[to], from)
					}
				}
			}
		}
	}

	reachable := make([]bool, fullSize)
	queue := make([]int, 0, fullSize)
	reachable[0] = true
	queue = append(queue, 0)

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, to := range fullEdges[v] {
			if !reachable[to] {
				reachable[to] = true
				queue = append(queue, to)
			}
		}
	}

	canReturn := make([]bool, fullSize)
	queue = queue[:0]
	canReturn[0] = true
	queue = append(queue, 0)

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, from := range reverseEdges[v] {
			if !canReturn[from] {
				canReturn[from] = true
				queue = append(queue, from)
			}
		}
	}

	newID := make([]int, fullSize)
	for i := range newID {
		newID[i] = -1
	}

	stateCount := 0
	for i := 0; i < fullSize; i++ {
		if reachable[i] && canReturn[i] {
			newID[i] = stateCount
			stateCount++
		}
	}

	edges := make([][]int, stateCount)
	for from := 0; from < fullSize; from++ {
		if newID[from] < 0 {
			continue
		}
		nf := newID[from]
		for _, to := range fullEdges[from] {
			if newID[to] >= 0 {
				edges[nf] = append(edges[nf], newID[to])
			}
		}
	}

	termCount := 2 * stateCount
	sequence := make([]int64, termCount)
	vector := make([]int64, stateCount)
	vector[newID[0]] = 1

	for step := 0; step < termCount; step++ {
		sequence[step] = vector[newID[0]]
		if step+1 == termCount {
			break
		}

		nextVector := make([]int64, stateCount)
		for from, value := range vector {
			if value == 0 {
				continue
			}
			for _, to := range edges[from] {
				nextVector[to] += value
				if nextVector[to] >= mod {
					nextVector[to] -= mod
				}
			}
		}
		vector = nextVector
	}

	if m < int64(len(sequence)) {
		fmt.Println(sequence[m])
		return
	}

	recurrence := berlekampMassey(sequence)
	fmt.Println(linearRecurrenceNth(sequence, recurrence, m))
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

const MOD int64 = 998244353

type Edge struct {
	to     int
	length int
	count  int64
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func berlekampMassey(s []int64) []int64 {
	c := []int64{1}
	b := []int64{1}
	l, shift := 0, 1
	last := int64(1)

	for pos := 0; pos < len(s); pos++ {
		delta := s[pos]
		for i := 1; i <= l; i++ {
			delta = (delta + c[i]*s[pos-i]) % MOD
		}
		if delta == 0 {
			shift++
			continue
		}

		oldC := append([]int64(nil), c...)
		coef := delta * modPow(last, MOD-2) % MOD

		required := len(b) + shift
		if len(c) < required {
			c = append(c, make([]int64, required-len(c))...)
		}
		for i := 0; i < len(b); i++ {
			c[i+shift] = (c[i+shift] - coef*b[i]) % MOD
			if c[i+shift] < 0 {
				c[i+shift] += MOD
			}
		}

		if 2*l <= pos {
			l = pos + 1 - l
			b = oldC
			last = delta
			shift = 1
		} else {
			shift++
		}
	}

	rec := make([]int64, l)
	for i := 0; i < l; i++ {
		rec[i] = (MOD - c[i+1]) % MOD
	}
	return rec
}

func combine(a, b, rec []int64) []int64 {
	k := len(rec)
	tmp := make([]int64, 2*k-1)

	for i := 0; i < k; i++ {
		if a[i] == 0 {
			continue
		}
		for j := 0; j < k; j++ {
			if b[j] == 0 {
				continue
			}
			tmp[i+j] = (tmp[i+j] + a[i]*b[j]) % MOD
		}
	}

	for i := 2*k - 2; i >= k; i-- {
		if tmp[i] == 0 {
			continue
		}
		v := tmp[i]
		for j := 1; j <= k; j++ {
			tmp[i-j] = (tmp[i-j] + v*rec[j-1]) % MOD
		}
	}

	return tmp[:k]
}

func linearRecurrenceTerm(initial, rec []int64, index int64) int64 {
	if index < int64(len(initial)) {
		return initial[index]
	}

	k := len(rec)
	if k == 0 {
		return 0
	}

	result := make([]int64, k)
	base := make([]int64, k)
	result[0] = 1

	if k == 1 {
		base[0] = rec[0]
	} else {
		base[1] = 1
	}

	for index > 0 {
		if index&1 == 1 {
			result = combine(result, base, rec)
		}
		base = combine(base, base, rec)
		index >>= 1
	}

	answer := int64(0)
	for i := 0; i < k; i++ {
		answer = (answer + result[i]*initial[i]) % MOD
	}
	return answer
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	words := make([]string, n)
	suffixSet := make(map[string]bool)
	maxLen := 0

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &words[i])
		if len(words[i]) > maxLen {
			maxLen = len(words[i])
		}
		for j := 0; j < len(words[i]); j++ {
			suffixSet[words[i][j:]] = true
		}
	}

	topID := make(map[string]int)
	bottomID := make(map[string]int)
	suffixes := make([]string, 0, len(suffixSet))
	for s := range suffixSet {
		suffixes = append(suffixes, s)
	}

	stateCount := 1
	for _, s := range suffixes {
		topID[s] = stateCount
		stateCount++
	}
	for _, s := range suffixes {
		bottomID[s] = stateCount
		stateCount++
	}

	graph := make([][]Edge, stateCount)

	addComparison := func(from int, top, bottom string) {
		common := 0
		if len(top) < len(bottom) {
			common = len(top)
		} else {
			common = len(bottom)
		}

		if top[:common] != bottom[:common] {
			return
		}

		to := 0
		if len(top) > len(bottom) {
			to = topID[top[len(bottom):]]
		} else if len(bottom) > len(top) {
			to = bottomID[bottom[len(top):]]
		}

		graph[from] = append(graph[from], Edge{
			to:     to,
			length: common,
			count:  1,
		})
	}

	for _, top := range words {
		for _, bottom := range words {
			addComparison(0, top, bottom)
		}
	}

	for _, residual := range suffixes {
		from := topID[residual]
		for _, bottom := range words {
			addComparison(from, residual, bottom)
		}
	}

	for _, residual := range suffixes {
		from := bottomID[residual]
		for _, top := range words {
			addComparison(from, top, residual)
		}
	}

	dimensionBound := stateCount * maxLen
	termCount := 2*dimensionBound + 10

	dp := make([][]int64, termCount)
	for i := range dp {
		dp[i] = make([]int64, stateCount)
	}
	dp[0][0] = 1

	for length := 0; length < termCount; length++ {
		for state := 0; state < stateCount; state++ {
			value := dp[length][state]
			if value == 0 {
				continue
			}
			for _, edge := range graph[state] {
				nextLength := length + edge.length
				if nextLength >= termCount {
					continue
				}
				dp[nextLength][edge.to] = (dp[nextLength][edge.to] + value*edge.count) % MOD
			}
		}
	}

	sequence := make([]int64, termCount)
	for i := 0; i < termCount; i++ {
		sequence[i] = dp[i][0]
	}

	if m < int64(termCount) {
		out := bufio.NewWriter(os.Stdout)
		fmt.Fprintln(out, sequence[m])
		out.Flush()
		return
	}

	recurrence := berlekampMassey(sequence)
	initial := sequence[:len(recurrence)]
	answer := linearRecurrenceTerm(initial, recurrence, m)

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}
